function prepareStructuredCommandCase(command){
  const adapter=createStructuredConsumerAdapter('learn'),registry=new CommandRegistry();adapter.bindSharedCommands(registry);
  const blocks=()=>adapter.snapshot().blocks,first=()=>blocks()[0],second=()=>blocks()[1],last=()=>blocks().at(-1);
  let context={mode:'edit'};
  if(command==='history.undo'){adapter.updateBlock(first().id,{html:'changed for undo'});}
  else if(command==='history.redo'){adapter.updateBlock(first().id,{html:'changed for redo'});adapter.undo();}
  else if(command==='block.insert')context={mode:'edit',target:{kind:'gap',parentId:null,index:1,depth:0},block:{id:'vs05-read-insert',type:'paragraph',html:'inserted'}};
  else if(command==='block.duplicate')context={mode:'edit',blockId:first().id};
  else if(command==='block.delete')context={mode:'edit',blockId:last().id};
  else if(command==='block.deleteMany')context={mode:'edit',blockIds:[first().id,last().id]};
  else if(command==='block.moveUp')context={mode:'edit',blockId:second().id};
  else if(command==='block.moveDown')context={mode:'edit',blockId:first().id};
  else if(command==='block.moveStart')context={mode:'edit',blockId:second().id};
  else if(command==='block.moveEnd')context={mode:'edit',blockId:first().id};
  else if(command==='block.moveToGap')context={mode:'edit',blockId:second().id,target:{kind:'gap',parentId:null,index:0,depth:0}};
  else if(command==='block.indent'){
    const candidate=blocks().find(block=>adapter.availability('block.indent',{mode:'edit',blockId:block.id}).enabled);context={mode:'edit',blockId:candidate.id};
  }
  else if(command==='block.outdent'){
    const candidate=blocks().find(block=>adapter.availability('block.indent',{mode:'edit',blockId:block.id}).enabled);adapter.mutateStructure({type:'indent',blockId:candidate.id});context={mode:'edit',blockId:candidate.id};
  }
  else if(command==='block.split')context={mode:'edit',blockId:second().id,before:'left',newBlock:{id:'vs05-read-split',type:'paragraph',html:'right'}};
  else if(command==='block.mergeBackward')context={mode:'edit',blockId:second().id,plainText:'merged text'};
  else if(command==='block.mergeForward')context={mode:'edit',blockId:first().id};
  else if(command==='block.convert')context={mode:'edit',blockId:first().id,to:'paragraph',sourceHtml:first().html,sourceText:'حدود الثقة والتحقق'};
  else if(command==='block.plainText')context={mode:'edit',blockId:first().id,sourceHtml:first().html,sourceText:'حدود الثقة والتحقق'};
  else if(command==='block.align')context={mode:'edit',blockId:first().id,value:'center'};
  else if(command==='block.direction')context={mode:'edit',blockId:first().id,value:'rtl'};
  else if(command==='block.background')context={mode:'edit',blockId:first().id,value:'soft'};
  else if(command==='block.clearStyle'){adapter.updateBlock(first().id,{align:'center',dir:'rtl',bg:'soft'});context={mode:'edit',blockId:first().id};}
  else if(command==='document.recoverAsNew'){
    const recovery=adapter.captureRecovery('vs05-read-mode-test');adapter.updateBlock(first().id,{html:'changed after recovery capture'});context={mode:'edit',recoveryId:recovery.id};
  }
  return {adapter,registry,context};
}
const structuredCommandState=(adapter,registry)=>({document:JSON.stringify(adapter.snapshot()),transaction:JSON.stringify(adapter.transactionDescriptor()),adapterReceipts:adapter.receipts.length,registryReceipts:registry.receipts.length});
const sameStructuredCommandState=(a,b)=>a.document===b.document&&a.transaction===b.transaction&&a.adapterReceipts===b.adapterReceipts&&a.registryReceipts===b.registryReceipts;

