 test('w2a.command-bus-shared-capability-action-surface','one bus instance','register command capability and action surface through compatibility facades','SemanticCommandBus','generic registries are delegates over one identity graph',()=>{const bus=new SemanticCommandBus(),r=new CommandRegistry(bus),c=new CapabilityRegistry(bus),a=new ActionSurfaceRegistry(r);r.register('x','CommandOwner','X',()=>true);c.register('cap','CapabilityOwner',()=>true);a.register('surface','SurfaceOwner',{presentation:'menu',routes:['context'],commands:['x'],exitRoutes:['Escape']});assert(c.capabilities===bus.capabilities&&a.surfaces===bus.actionSurfaces&&a.validate()&&c.inspect('cap').owner==='CapabilityOwner')});
 test('w3a.global-input-owner-contract','new leaf owner without bootstrap listener ownership','inspect canonical descriptors','GlobalInputKeymapOwner','one canonical owner declares Controller integration as listener owner',()=>{const bus=new SemanticCommandBus(),owner=new GlobalInputKeymapOwner({commands:bus});const d=owner.descriptor();assert(owner.owner===GLOBAL_INPUT_KEYMAP_OWNER&&GLOBAL_INPUT_KEYMAP_CONTRACT.owner===GLOBAL_INPUT_KEYMAP_OWNER&&GLOBAL_INPUT_OWNERSHIP_CONTRACT.owner===GLOBAL_INPUT_KEYMAP_OWNER&&REGION_CYCLE_CONTRACT.owner===GLOBAL_INPUT_KEYMAP_OWNER&&d.listenerOwnership==='ControllerIntegrationHost')});
